#!/bin/bash
set -euo pipefail
cd "$(dirname "$0")/.."
if [[ "${KORE_HARDWARE_TEST_ENABLED:-}" != "YES" ]]; then
  echo "Hardware test is opt-in: set KORE_HARDWARE_TEST_ENABLED=YES" >&2
  exit 2
fi
if [[ "${KORE_AUDIO_INPUT_INDEX:-}" == "" ]]; then
  echo "Configure KORE_AUDIO_INPUT_INDEX before running." >&2
  exit 2
fi
mkdir -p artifacts
# Hardware audio must be generated by a separately validated, bounded driver.
# No automatic playback here: avoid reproducing prior loud/high-frequency noise.
echo "Capture will start now. Start the 440 Hz stereo signal through the KORE driver externally."
bash automation/capture_loopback.sh artifacts/loopback.wav
python3 automation/check_audio.py artifacts/loopback.wav --report artifacts/audio-report.json
